oxygen tanks the light oxygen tank is an oxygen storage tank that can hold up to 1000 units of air. it is used to provide a portable source of oxygen while in areas that do not have an oxygen source of their own.

usage:
up to two oxygen tanks can be worn at a time. to wear any type of oxygen tank, open your inventory and click on the galacticraft tab at the top of the menu. here you will see the available spots for your various types of equipment. simply place your tank(s) in one of the slots with a gray picture of an oxygen tank. other types of oxygen tanks include the medium oxygen tank, which holds twice the amount of oxygen as a light tank, and the heavy oxygen tank, which holds three times the amount of a light tank. {"0": {"autoconsume": 0, "consume": 0, "groupdetect": 0, "ignorenbt": 0, "index": 1, "partialmatch": 1, "requireonlyoneitem": 0, "requireditems": {"0": {"count": 2, "damage": 1000, "oredict": "", "id": "galacticraftcore:item.oxygentanklightfull", "resolved": {"id": "i:galacticraftcore:item.oxygentanklightfull:1000", "name": "light oxygen tank", "mod": "galacticraftcore", "registry": "item.oxygentanklightfull", "icon": 7579, "nbt": null, "kind": "item", "unit": "items", "damage": 1000, "shard": "454b4d430c8d805c", "recipes": 3}, "label": "light oxygen tank"}}, "taskid": "bq_standard:retrieval"}} {"0": {"choices": {"0": {"count": 4, "damage": 0, "oredict": "", "id": "galacticraftcore:tile.oxygenpipe", "resolved": {"id": "i:galacticraftcore:tile.oxygenpipe:0", "name": "oxygen pipe", "mod": "galacticraftcore", "registry": "tile.oxygenpipe", "icon": 7672, "nbt": null, "kind": "item", "unit": "items", "damage": 0, "shard": "4dc8129cf5e6ccc6", "recipes": 1}, "label": "oxygen pipe"}, "1": {"count": 4, "damage": 8, "oredict": "", "id": "galacticraftcore:item.basicitem", "resolved": {"id": "i:galacticraftcore:item.basicitem:8", "name": "compressed aluminium plate", "mod": "galacticraftcore", "registry": "item.basicitem", "icon": 7543, "nbt": null, "kind": "item", "unit": "items", "damage": 8, "shard": "42e52c7c7f45ae8b", "recipes": 5}, "label": "compressed aluminium plate"}, "2": {"count": 1, "damage": 13, "oredict": "", "id": "galacticraftcore:item.basicitem", "resolved": 