temperature control the ambient thermal controller is an item for use in the oxygen sealer to provide thermal protection in sealed spaces.

an ambient thermal controller is useful in the dimensions too cold or too hot for players to survive without thermal padding.

it can be placed in the 3rd slot next to the energy and oxygen slots in a working oxygen sealer. once the ambient thermal controller is in the sealer, it will heat or cool the output oxygen according to the local environment, and then the player can safely take the thermal padding off in the sealed room. though there's absolutely no reason to do so. {"0": {"autoconsume": 0, "consume": 0, "groupdetect": 0, "ignorenbt": 0, "index": 0, "partialmatch": 1, "requireonlyoneitem": 0, "requireditems": {"0": {"count": 1, "damage": 20, "oredict": "", "id": "galacticraftcore:item.basicitem", "resolved": {"id": "i:galacticraftcore:item.basicitem:20", "name": "ambient thermal controller", "mod": "galacticraftcore", "registry": "item.basicitem", "icon": 7540, "nbt": null, "kind": "item", "unit": "items", "damage": 20, "shard": "fe56698e13231349", "recipes": 1}, "label": "ambient thermal controller"}}, "taskid": "bq_standard:retrieval"}} {"0": {"choices": {"0": {"count": 10, "damage": 0, "oredict": "", "id": "galacticraftcore:tile.oxygenpipe", "resolved": {"id": "i:galacticraftcore:tile.oxygenpipe:0", "name": "oxygen pipe", "mod": "galacticraftcore", "registry": "tile.oxygenpipe", "icon": 7672, "nbt": null, "kind": "item", "unit": "items", "damage": 0, "shard": "4dc8129cf5e6ccc6", "recipes": 1}, "label": "oxygen pipe"}, "1": {"count": 2, "damage": 5, "oredict": "", "id": "galacticraftmars:item.null", "resolved": {"id": "i:galacticraftmars:item.null:5", "name": "compressed desh plate", "mod": "galacticraftmars", "registry": "item.null", "icon": 7719, "nbt": null, "kind": "item", "unit": "items", "damage": 5, "shard": "8a4374e67096c2c9", "recipes": 5}, "label": "compressed desh plate"}, "2": {"count": 2, "damage": 13, "oredict": "", "id": "galacticraftcore:item.basicitem", "resolved": {"id": "i:galacticraftcore:item.basicitem:13", "name": "basic wafer", "mod": "galacticraftcore", "registry": "item.basicitem", "icon": 7532, "nbt": null, "kind": "item", "unit": "items", "damage": 13, "